/* ==========================================================================
   Pixel Vending Machine Stylesheet
   Palette:
   1. Dark Navy/Slate (Base Shadow): #1a1c23
   2. Retro Teal/Cyan (Main Cabinet): #2b5c68
   3. Golden Yellow (Accent/Highlights): #f6d258
   4. CRT Screen Green (Display Glow): #4deeea
   5. Deep Red/Orange (Snack Accent): #e0533c
   ========================================================================== */

:root {
  --col-dark: #1a1c23;
  --col-cabinet: #2b5c68;
  --col-cabinet-dark: #1b3d46;
  --col-cabinet-light: #3d7988;
  --col-accent: #f6d258;
  --col-screen-bg: #0d1a1b;
  --col-screen-text: #4deeea;
  --col-screen-dim: #267977;
  --col-card: #fdfdfd;
  --col-red: #e0533c;
  --col-cookie: #c4823f;
  --border-thick: 4px solid var(--col-dark);
  --pixel-shadow: 4px 4px 0px var(--col-dark);
}

[hidden] {
  display: none !important;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: #232733;
  background-image:
    radial-gradient(circle at 50% 50%, #2f3546 15%, transparent 16%),
    radial-gradient(circle at 0% 0%, #282d3b 25%, transparent 26%);
  background-size: 32px 32px;
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  color: var(--col-dark);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.5rem 1rem;
}

/* Cabinet Layout */
.vending-cabinet {
  width: 100%;
  max-width: 440px;
  background-color: var(--col-cabinet);
  border: var(--border-thick);
  border-top-color: var(--col-cabinet-light);
  border-left-color: var(--col-cabinet-light);
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.45);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cabinet-header {
  background-color: var(--col-cabinet-dark);
  border: var(--border-thick);
  padding: 0.6rem;
  text-align: center;
  box-shadow: inset 2px 2px 0px rgba(255, 255, 255, 0.15);
}

.machine-title {
  font-size: 1.35rem;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--col-accent);
  text-shadow: 2px 2px 0px var(--col-dark);
}

/* Showcase Window */
.window-frame {
  background: #111e22;
  border: var(--border-thick);
  padding: 0.85rem;
  box-shadow: inset 4px 4px 0px rgba(0, 0, 0, 0.6);
}

.snack-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

/* Snack Buttons */
.snack-slot {
  appearance: none;
  background-color: #21353b;
  border: 3px solid #142226;
  border-top-color: #3b5a63;
  border-left-color: #3b5a63;
  padding: 0.6rem 0.4rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
  font-family: inherit;
  color: #fff;
  box-shadow: var(--pixel-shadow);
  transition: transform 0.05s ease, background-color 0.1s ease;
}

.snack-slot:hover {
  background-color: #2f4b54;
  border-color: var(--col-accent);
}

.snack-slot:focus-visible {
  outline: 3px solid var(--col-accent);
  outline-offset: 2px;
}

.snack-slot:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px var(--col-dark);
}

.snack-name {
  font-size: 0.95rem;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.snack-cost {
  font-size: 0.95rem;
  font-weight: 900;
  background: var(--col-dark);
  color: var(--col-accent);
  padding: 0.1rem 0.4rem;
  border: 1px solid var(--col-accent);
}

/* Pure CSS Pixel Icons */
.pixel-art {
  display: inline-block;
  width: 28px;
  height: 28px;
  image-rendering: pixelated;
}

/* Chips Bag */
.art-chips {
  background:
    linear-gradient(var(--col-red), var(--col-red)) 4px 4px / 20px 22px no-repeat,
    linear-gradient(var(--col-accent), var(--col-accent)) 8px 10px / 12px 6px no-repeat;
  box-shadow:
    inset -3px 0 0 rgba(0, 0, 0, 0.3),
    0 0 0 2px var(--col-dark);
}

/* Soda Can */
.art-soda {
  background:
    linear-gradient(#8892b0, #8892b0) 6px 2px / 16px 4px no-repeat,
    linear-gradient(var(--col-screen-text), #1c7c7a) 6px 6px / 16px 20px no-repeat;
  border-radius: 2px;
  box-shadow:
    inset 2px 0 0 rgba(255, 255, 255, 0.4),
    0 0 0 2px var(--col-dark);
}

/* Bit Candy */
.art-candy {
  width: 26px;
  height: 26px;
  background:
    linear-gradient(45deg, var(--col-accent) 25%, #f272a1 25%, #f272a1 50%, var(--col-accent) 50%, var(--col-accent) 75%, #f272a1 75%);
  border-radius: 50%;
  box-shadow:
    0 0 0 2px var(--col-dark),
    inset -2px -2px 0 rgba(0, 0, 0, 0.3);
}

/* Mega Cookie */
.art-cookie {
  width: 26px;
  height: 26px;
  background: var(--col-cookie);
  border-radius: 50%;
  box-shadow:
    inset 4px 4px 0 #3a1e05,
    inset -6px -6px 0 #3a1e05,
    inset 2px -4px 0 #3a1e05,
    0 0 0 2px var(--col-dark);
}

/* Screen and Coin Controls */
.control-panel {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.screen {
  background-color: var(--col-screen-bg);
  border: var(--border-thick);
  padding: 0.75rem;
  box-shadow: inset 2px 2px 6px rgba(0, 0, 0, 0.8);
}

.screen-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px dashed var(--col-screen-dim);
  padding-bottom: 0.4rem;
  margin-bottom: 0.4rem;
}

.screen-label {
  font-size: 1rem;
  color: var(--col-screen-dim);
  font-weight: bold;
}

.screen-value {
  font-size: 1.25rem;
  font-weight: 900;
  color: var(--col-screen-text);
  text-shadow: 0 0 6px rgba(77, 238, 234, 0.4);
}

.screen-status {
  font-size: 1rem;
  font-weight: bold;
  color: var(--col-accent);
  min-height: 1.4rem;
  line-height: 1.4;
}

.coin-controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 900;
  color: var(--col-dark);
  background-color: var(--col-accent);
  border: var(--border-thick);
  border-top-color: #ffefa3;
  border-left-color: #ffefa3;
  padding: 0.65rem 0.5rem;
  cursor: pointer;
  box-shadow: var(--pixel-shadow);
  transition: transform 0.05s ease, background-color 0.1s ease;
}

.pixel-btn:hover {
  background-color: #ffd866;
}

.pixel-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px var(--col-dark);
}

/* Chute Area */
.chute-area {
  background-color: var(--col-cabinet-dark);
  border: var(--border-thick);
  padding: 0.65rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.chute-flap {
  width: 100%;
  background-color: #122126;
  border: 3px solid #081114;
  text-align: center;
  padding: 0.4rem;
  box-shadow: inset 0 -3px 0 rgba(255, 255, 255, 0.1);
}

.chute-label {
  font-size: 0.9rem;
  font-weight: 900;
  letter-spacing: 3px;
  color: #557984;
}

.dispensed-tray {
  width: 100%;
  min-height: 32px;
  text-align: center;
  font-weight: bold;
  font-size: 0.95rem;
  color: var(--col-screen-text);
}

.dispensed-badge {
  display: inline-block;
  background-color: var(--col-dark);
  border: 2px solid var(--col-screen-text);
  padding: 0.2rem 0.6rem;
  animation: popIn 0.2s ease-out;
}

@keyframes popIn {
  from {
    transform: scale(0.8);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // State stored in cents to prevent floating-point rounding issues
  let currentCreditCents = 0;

  // DOM references
  const creditDisplay = document.getElementById('credit-display');
  const statusMessage = document.getElementById('status-message');
  const dispensedTray = document.getElementById('dispensed-tray');
  const btnInsert25 = document.getElementById('btn-insert-25');
  const btnInsert100 = document.getElementById('btn-insert-100');
  const snackButtons = document.querySelectorAll('.snack-slot');

  /**
   * Format integer cents into currency string: e.g. 125 -> "$1.25"
   * @param {number} cents
   * @returns {string}
   */
  function formatCurrency(cents) {
    return `$${(cents / 100).toFixed(2)}`;
  }

  /**
   * Update credit display on screen
   */
  function updateCreditDisplay() {
    creditDisplay.textContent = formatCurrency(currentCreditCents);
  }

  /**
   * Insert coin handler
   * @param {number} centsToAdd
   */
  function insertCredit(centsToAdd) {
    currentCreditCents += centsToAdd;
    updateCreditDisplay();
    statusMessage.textContent = `Inserted ${formatCurrency(centsToAdd)}`;
  }

  /**
   * Attempt snack purchase
   * @param {HTMLButtonElement} button
   */
  function handleSnackClick(button) {
    const snackName = button.getAttribute('data-name') || 'Snack';
    const priceDecimal = parseFloat(button.getAttribute('data-price') || '0');
    const priceCents = Math.round(priceDecimal * 100);

    if (currentCreditCents >= priceCents) {
      const changeCents = currentCreditCents - priceCents;
      currentCreditCents = 0;
      updateCreditDisplay();

      const changeFormatted = formatCurrency(changeCents);
      statusMessage.textContent = `Dispensed ${snackName}! Change: ${changeFormatted}`;

      // Render dispensed badge in the tray
      dispensedTray.innerHTML = `<span class="dispensed-badge">* ${snackName} *</span>`;
    } else {
      statusMessage.textContent = 'Not enough credit';
    }
  }

  // Event listeners for inserting credit
  btnInsert25.addEventListener('click', () => {
    insertCredit(25);
  });

  btnInsert100.addEventListener('click', () => {
    insertCredit(100);
  });

  // Event listeners for snacks
  snackButtons.forEach(button => {
    button.addEventListener('click', () => {
      handleSnackClick(button);
    });
  });

  // Initial render
  updateCreditDisplay();
});
